import java.util.*;

public class Main {
    List<String> findRepeatedDnaSequences(String s) {
        Map<String, Integer> counts = new HashMap<>();
        int n = s.length();
        for (int i = 0; i <= n - 10; i++) {
            String window = s.substring(i, i + 10);                    // extract and hash the full 10 character string
            counts.put(window, counts.getOrDefault(window, 0) + 1);
        }
        List<String> result = new ArrayList<>();
        for (Map.Entry<String, Integer> entry : counts.entrySet()) {
            if (entry.getValue() > 1) result.add(entry.getKey());
        }
        return result;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.findRepeatedDnaSequences("AAAAACCCCCAAAAACCCCCCAAAAAGGGTTT"));
    }
}

