        }
        Map<Integer, Integer> counts = new HashMap<>();
        for (int i = 9; i < n; i++) {
            encoding = ((encoding << 2) | code.get(s.charAt(i))) & mask;   // roll the window forward by one character
            int count = counts.getOrDefault(encoding, 0) + 1;
            counts.put(encoding, count);
            if (count == 2) result.add(s.substring(i - 9, i + 1));
        }
        return result;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.findRepeatedDnaSequences("AAAAACCCCCAAAAACCCCCCAAAAAGGGTTT"));
