#include <bits/stdc++.h>
using namespace std;

vector<string> findRepeatedDnaSequences(string s) {
    int n = (int)s.size();
    vector<string> result;
    if (n < 10) return result;
    unordered_map<char, int> code = {{'A',0},{'C',1},{'G',2},{'T',3}};
    int mask = (1 << 20) - 1;
    int encoding = 0;
    for (int i = 0; i < 9; i++) {
        encoding = (encoding << 2) | code[s[i]];                        // build the first 9 characters' encoding
    }
    unordered_map<int, int> counts;
    for (int i = 9; i < n; i++) {
        encoding = ((encoding << 2) | code[s[i]]) & mask;                 // roll the window forward by one character
        int count = ++counts[encoding];
        if (count == 2) result.push_back(s.substr(i - 9, 10));
    }
    return result;
}

int main() {
    vector<string> result = findRepeatedDnaSequences("AAAAACCCCCAAAAACCCCCCAAAAAGGGTTT");
    for (auto& seq : result) cout << seq << " ";
